mapper.select:
SELECT o.user_id
  FROM oauth_accounts o
  JOIN users u ON u.id = o.user_id
 WHERE o.provider          = #{provider}
   AND o.provider_user_id  = #{providerUserId}
   AND u.status <> 'WITHDRAWN'

SELECT EXISTS (
    SELECT 1 FROM oauth_accounts
     WHERE user_id = #{userId} AND provider = #{provider}
)
